  const deepRow = () => (bk.deep ? [['<b>発展</b>・折りたたみ', '深く学ぶ中身です。初めて読むときは飛ばしてかまいません。目次に「発展」の札が付きます。']] : []);
  const marksDrawn = () => typeof B.secMarks === 'function';
